import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.MalformedURLException;
import java.net.URL;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.net.URI;
import java.util.regex.Pattern;

public class SecureWebApp {
    // Define a strict whitelist pattern for allowed schemes
    private static final Pattern ALLOWED_SCHEME_PATTERN = Pattern.compile("^(https?$)$");

    public static void main(String[] args) throws Exception {
        String userInput = "https://example.com/data";

        if (!isValidUrl(userInput)) {
            throw new IllegalArgumentException("Invalid URL provided");
        }

        // Use HttpClient with built-in redirect protection and secure handling
        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(userInput))
                .GET()
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        System.out.println(response.body());
    }

    private static boolean isValidUrl(String urlString) {
        try {
            URL url = new URL(urlString);
            // Validate the scheme against a whitelist to prevent SSRF attacks
            if (!ALLOWED_SCHEME_PATTERN.matcher(url.getProtocol()).matches()) {
                return false;
            }
            // Additional checks could be added here (e.g., checking host IP ranges)
            return true;
        } catch (MalformedURLException e) {
            return false;
        }
    }
}
